// Recebe a resposta da API (lista de contatos) ou o erro da chamada.
// Guarda o último contato avisado e conta falhas seguidas na memória do fluxo.
const state = $getWorkflowStaticData('global');
const cfg = $('Configuração').first().json;
const r = $input.first().json;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];

const ok = r.statusCode === 200 && Array.isArray(r.body);

if (!ok) {
  // Falha: timeout, API fora, senha errada (401), erro 500...
  const detalhe = r.error?.message || r.error || (r.statusCode ? `HTTP ${r.statusCode}: ${JSON.stringify(r.body).slice(0, 200)}` : 'sem detalhes');
  state.failures = (state.failures || 0) + 1;
  if (state.failures >= cfg.falhasParaAlerta && !state.apiDown) {
    state.apiDown = true;
    out.push({ json: { text: `🚨 <b>Site/API com problema</b>\n${state.failures} verificações seguidas falharam.\n\n<code>${esc(String(detalhe).slice(0, 300))}</code>\n\nPainel: ${esc(cfg.siteUrl)}/admin` } });
  }
  return out;
}

if (state.apiDown) {
  out.push({ json: { text: `✅ <b>API voltou</b>\nRespondendo normalmente depois de ${state.failures} verificações com falha.` } });
}
state.failures = 0;
state.apiDown = false;

const contatos = r.body.filter((c) => c && typeof c.id === 'number');
const maxId = contatos.reduce((m, c) => Math.max(m, c.id), 0);

// Primeira execução: só marca onde parou, sem avisar contatos antigos.
if (state.lastId === undefined) {
  state.lastId = maxId;
  out.push({ json: { text: `🐺 <b>Monitor da Wolf Solutions ligado</b>\nVou te avisar aqui a cada contato novo do site.\nContatos já existentes: ${contatos.length}.` } });
  return out;
}
// Banco foi zerado (ids recomeçaram): volta o marcador.
if (maxId < state.lastId) state.lastId = 0;

const origem = { quiz: 'Diagnóstico de IA', form: 'Formulário de contato' };
const novos = contatos.filter((c) => c.id > state.lastId).sort((a, b) => a.id - b.id);

for (const c of novos) {
  const quando = DateTime.fromISO(c.created_at).setZone(cfg.fuso).toFormat('dd/MM HH:mm');
  const linhas = [
    `🔔 <b>Novo contato no site</b> (${esc(origem[c.source] || c.source)})`,
    '',
    `👤 <b>${esc(c.name)}</b>${c.company ? ` — ${esc(c.company)}` : ''}`,
  ];
  if (c.whatsapp) {
    let num = String(c.whatsapp).replace(/\D/g, '');
    if (num.length <= 11) num = '55' + num;
    linhas.push(`📱 WhatsApp: <a href="https://wa.me/${num}">${esc(c.whatsapp)}</a>`);
  }
  if (c.email) linhas.push(`✉️ ${esc(c.email)}`);
  if (c.message) {
    const msg = String(c.message);
    linhas.push('', `💬 ${esc(msg.length > 700 ? msg.slice(0, 700) + '…' : msg)}`);
  }
  linhas.push('', `🕒 ${quando} · #${c.id} · <a href="${esc(cfg.siteUrl)}/admin">abrir painel</a>`);
  out.push({ json: { text: linhas.join('\n') } });
}

state.lastId = Math.max(state.lastId, maxId);
return out;

// Monta o resumo diário a partir de /api/admin/summary.
const cfg = $('Configuração').first().json;
const s = $input.first().json;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const top = (obj) =>
  Object.entries(obj || {})
    .slice(0, 3)
    .map(([k, v]) => `${esc(k)} (${v})`)
    .join(', ') || '—';

const text = [
  '☀️ <b>Bom dia! Resumo do site</b>',
  '',
  `📥 Contatos: <b>${s.total_contacts}</b> no total — <b>${s.new_contacts}</b> ainda como "novo"`,
  `🧭 Diagnósticos: <b>${s.quiz_last_7_days}</b> nos últimos 7 dias (${s.total_quiz} no total)`,
  `🏷️ Ramos que mais aparecem: ${top(s.by_sector)}`,
  '',
  `Painel: ${esc(cfg.siteUrl)}/admin`,
].join('\n');

return [{ json: { text } }];
